class Solution {
    public int jump(int[] nums) {
        int length = nums.length;
        int[] jumps = new int[length];
        int unreachable = length + 1;
        java.util.Arrays.fill(jumps, unreachable);
        jumps[0] = 0;
        for (int index = 0; index < length; index++) {
            int end = (int) Math.min(length - 1L, (long) index + nums[index]);
            for (int next = index + 1; next <= end; next++) {
                jumps[next] = Math.min(jumps[next], jumps[index] + 1);
            }
        }
        return jumps[length - 1];
    }
}

